            //
            aOrbiterD = ((aOrbiterD + aOrbiterJ) + 0x60DC348082AA9B92ULL) + aOUSaltH[(((511U - aIndex) + 299U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterD) ^ 0x3BE810A1364D38A3ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x930E296F150E2F07ULL), 27U);
