            aWandererF = aWandererF ^ (((RotL64(aScatter, 21U) + RotL64(aOrbiterD, 57U)) + aOrbiterE) + aWUSaltF[(((511U - aIndex) + 439U)) & S_SALT1]);
            aWandererB = aWandererB + ((RotL64(aPrevious, 5U) + aOrbiterK) + RotL64(aOrbiterF, 13U));
            aWandererG = aWandererG ^ ((RotL64(aCross, 57U) + RotL64(aOrbiterG, 30U)) + aOrbiterI);
            aWandererD = aWandererD + ((RotL64(aIngress, 43U) + RotL64(aOrbiterF, 43U)) + aOrbiterG);
            //
            aCarry = aCarry + (aWandererK ^ RotL64(aWandererG, 3U));
            aCarry = aCarry + (aWandererA ^ RotL64(aWandererI, 37U));
            aCarry = aCarry + (aWandererD ^ RotL64(aWandererE, 6U));
            aCarry = aCarry + (aWandererB ^ RotL64(aWandererJ, 47U));
