            //
            aOrbiterJ = (aOrbiterJ + aOrbiterD) + 0x0604FBA2E9AF14F4ULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterJ) ^ 0x7D93133D52304E19ULL) ^ aOUSaltG[((aIndex + 284U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0xF5250D2A7975F633ULL), 5U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterK) + 0x7B3911342E04E407ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterE) ^ 0x64448A3217D5ABF7ULL;
