            aOrbiterK = (aOrbiterK + aOrbiterF) + 0x26A87CDF1060B7CBULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterK) ^ 0x7A79AA9FBC7E8835ULL) ^ aOUSaltE[((aIndex + 508U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x463C33AA1E5931A3ULL), 39U);
