    std::uint64_t *aOUSaltF = pWorkSpace->mDomainBundle.mTwistSalts.mOrbiterUpdate.mSaltF;
    std::uint64_t *aOUSaltG = pWorkSpace->mDomainBundle.mTwistSalts.mOrbiterUpdate.mSaltG;
