            aCross = (RotL64(aMagmaLaneC[((S_BLOCK1 - aIndex + 2036U)) & S_BLOCK1], 53U) ^ RotL64(aMagmaLaneA[((S_BLOCK1 - aIndex + 4011U)) & S_BLOCK1], 43U));
