            aOrbiterD = ((aWandererJ + RotL64(aScatter, 43U)) + 0x26AB1084C5C06ABCULL) + aOASaltA[((aIndex + 283U)) & S_SALT1];
            aOrbiterI = ((aWandererE + RotL64(aPrevious, 57U)) + 0xEE2641D4D52A45D9ULL) + aOASaltH[(((511U - aIndex) + 405U)) & S_SALT1];
