            aWandererI = aWandererI + (((RotL64(aCross, 35U) + aOrbiterJ) + RotL64(aOrbiterE, 37U)) + aWUSaltG[(((511U - aIndex) + 176U)) & S_SALT1]);
            aWandererH = aWandererH ^ ((RotL64(aIngress, 37U) + RotL64(aOrbiterB, 12U)) + aOrbiterD);
