            aOrbiterD = RotL64((aOrbiterD * 0xCD54938B45E60461ULL), 57U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterF) + 0xB19FC874DB9EB447ULL) + aOUSaltA[((aIndex + 381U)) & S_SALT1];
