            aOrbiterA = RotL64((aOrbiterA * 0xC646AF6BD380CFBDULL), 3U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterC) + 0xB5E187F04D239F07ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterB) ^ 0x18F652978AEBFBCDULL;
