            //
            aOrbiterH = ((aOrbiterH + aOrbiterB) + 0x7427BCC5B77D4F52ULL) + aOUSaltE[((aIndex + 200U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterH) ^ 0xBE3B35C78C30F2DAULL;
            aOrbiterG = RotL64((aOrbiterG * 0x9E2645A94A503D9DULL), 23U);
