            aIngress = aIngress + (aOrbiterK ^ RotL64(aOrbiterJ, 23U));
            aIngress = aIngress + (aOrbiterA ^ RotL64(aOrbiterB, 14U));
            aIngress = aIngress + RotL64(aOrbiterH, 47U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererE = aWandererE + ((RotL64(aIngress, 41U) + aOrbiterB) + RotL64(aOrbiterA, 35U));
            aWandererC = aWandererC ^ ((RotL64(aScatter, 47U) + RotL64(aOrbiterH, 19U)) + aOrbiterD);
            aWandererG = aWandererG + ((RotL64(aPrevious, 50U) + RotL64(aOrbiterK, 27U)) + aOrbiterG);
            aWandererI = aWandererI ^ (((RotL64(aCross, 43U) + RotL64(aOrbiterD, 57U)) + aOrbiterF) + RotL64(aCarry, 23U));
            aWandererH = aWandererH + ((RotL64(aIngress, 5U) + aOrbiterE) + RotL64(aOrbiterB, 48U));
            aWandererJ = aWandererJ ^ (((RotL64(aScatter, 57U) + RotL64(aOrbiterG, 43U)) + aOrbiterC) + aWUSaltD[((aIndex + 459U)) & S_SALT1]);
