            aWandererB = aWandererB ^ (((RotL64(aCross, 39U) + aOrbiterC) + RotL64(aOrbiterH, 5U)) + aWUSaltE[((aIndex + 349U)) & S_SALT1]);
            aWandererF = aWandererF + (((RotL64(aIngress, 36U) + aOrbiterF) + RotL64(aOrbiterJ, 29U)) + aWUSaltF[((aIndex + 505U)) & S_SALT1]);
            aWandererA = aWandererA ^ (((RotL64(aScatter, 19U) + RotL64(aOrbiterA, 21U)) + aOrbiterI) + RotL64(aCarry, 47U));
