            //
            aOrbiterD = (aWandererG + RotL64(aCross, 19U)) + 0xAE41FD477A356C64ULL;
            aOrbiterF = ((aWandererA + RotL64(aIngress, 56U)) + RotL64(aCarry, 27U)) + 0xFB053A3DB1712E8AULL;
            aOrbiterK = ((aWandererD + RotL64(aScatter, 5U)) + 0x5A543F9B1B299335ULL) + aOASaltE[((aIndex + 207U)) & S_SALT1];
            aOrbiterC = (aWandererB + RotL64(aPrevious, 47U)) + 0xC1CFA64226A0D88AULL;
            aOrbiterG = (((aWandererK + RotL64(aCross, 29U)) + RotL64(aCarry, 11U)) + 0x74A0C8D6D1BBB11DULL) + aOASaltC[((aIndex + 146U)) & S_SALT1];
            aOrbiterH = ((aWandererH + RotL64(aIngress, 12U)) + 0xE740607B53FA8B27ULL) + aOASaltD[((aIndex + 343U)) & S_SALT1];
            aOrbiterI = (aWandererE + RotL64(aScatter, 43U)) + 0x838F55C477F145C8ULL;
            aOrbiterE = (aWandererF + RotL64(aPrevious, 3U)) + 0xF29CE61BAF3E9EE5ULL;
            aOrbiterB = ((aWandererJ + RotL64(aCross, 27U)) + RotL64(aCarry, 47U)) + 0x23A458B17D911221ULL;
            aOrbiterJ = (aWandererI + RotL64(aIngress, 21U)) + 0x951FC4417A1E62AAULL;
            aOrbiterA = ((aWandererC + RotL64(aScatter, 35U)) + 0x3EA93CAFA38593F7ULL) + aOASaltA[(((511U - aIndex) + 446U)) & S_SALT1];
            //
            aOrbiterD = (aOrbiterD + aOrbiterF) + 0x9E12A5C1F6E3AEEEULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterD) ^ 0xF04E47680EEBA9EEULL) ^ aOUSaltD[((aIndex + 491U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x4CD45F2119B167A1ULL), 41U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterG) + 0xD3DADF203AFE1DFDULL) + aOUSaltG[(((511U - aIndex) + 370U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterC) ^ 0x54D57ED6291F027CULL;
            aOrbiterH = RotL64((aOrbiterH * 0x24D1821A589C5507ULL), 13U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterK) + 0x0E7D18659285860FULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterI) ^ 0xABD4BABE2BAEE72AULL;
            aOrbiterE = RotL64((aOrbiterE * 0x4F2BE825352F3647ULL), 21U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterC) + 0x05EF26E26559BCFBULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterB) ^ 0x7320D1D96C0CC327ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xA5D471904D87D97BULL), 19U);
            //
