            aOrbiterF = (aOrbiterF ^ aOrbiterA) ^ 0xC1373A298CB770B8ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x417B625E05277541ULL), 23U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterE) + 0xBB81BABDC058857EULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterH) ^ 0xCC9EA8FECE75328EULL) ^ aOUSaltC[(((511U - aIndex) + 252U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0xA69D76D99E6936D9ULL), 57U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterA) + 0xBA8E6CD43F114E95ULL;
