            aOrbiterB = ((aOrbiterB ^ aOrbiterG) ^ 0x91BC1A0B71F058ADULL) ^ aOUSaltE[((aIndex + 251U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0xBCC99467840E4B0FULL), 53U);
