            aOrbiterE = (aOrbiterE + aOrbiterD) + 0xB89AFEC0F0BA3F8DULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterE) ^ 0x45DC05A2E9F2430BULL;
            aOrbiterI = RotL64((aOrbiterI * 0xAB24A9B393012A9BULL), 57U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterJ) + 0xBB9BF393AABF71E6ULL;
